INSERT INTO `{{PREFIX}}setting` (`store_id`, `code`, `key`, `value`, `serialized`) VALUES
(0, 'module_kristal_home', 'module_kristal_home_status', '1', 0),
(0, 'module_kristal_home', 'module_kristal_home_h1', 'Оренда посуду, меблів і обладнання для подій у Львові', 0),
(0, 'module_kristal_home', 'module_kristal_home_lead', 'Посуд, скло, меблі, текстиль, шатри й кухонне обладнання для весіль, банкетів, фуршетів і кейтерингу. Ціни за добу на сайті, доставка й вивезення, миття входить у вартість.', 0),
(0, 'module_kristal_home', 'module_kristal_home_hero_image', '', 0),
(0, 'module_kristal_home', 'module_kristal_home_meta_title', 'Оренда посуду у Львові — від 5 ₴/доба | Крістал', 0),
(0, 'module_kristal_home', 'module_kristal_home_meta_description', 'Оренда посуду, меблів, текстилю й обладнання для подій у Львові. Ціни за добу на сайті, доставка й вивезення. Розрахуємо замовлення за 15 хвилин.', 0),
(0, 'module_kristal_home', 'module_kristal_home_numbers', '[{"value":"з 2013","label":"працюємо у Львові"},{"value":"5000+","label":"позицій на складі"},{"value":"300+","label":"подій на рік"}]', 1),
(0, 'module_kristal_home', 'module_kristal_home_faq', '[{"q":"Чи треба мити посуд після події?","a":"Ні. Миття входить у вартість оренди — повертайте посуд без миття, але без залишків їжі."},{"q":"Яке мінімальне замовлення?","a":"Мінімальна кількість вказана в картці кожного товару — зазвичай від 10–20 одиниць."},{"q":"Що буде, якщо щось розіб''ється?","a":"Сплачується вартість відшкодування з картки товару. Невеликий бій на великих подіях обговорюємо окремо."},{"q":"Як швидко ви привезете замовлення?","a":"Доставляємо Львовом і областю в узгоджений час; у сезон весіль бронюйте заздалегідь."}]', 1),
(0, 'module_kristal_home', 'module_kristal_home_seo_text', '<h2>Оренда посуду у Львові</h2><p>«Крістал» здає в оренду посуд, столові прибори, скло, меблі, текстиль і обладнання для весіль, банкетів, фуршетів, корпоративів і кейтерингу. Ціни вказані за одиницю на добу, для великих подій діють знижки за обсяг.</p><p>Привеземо замовлення, заберемо після події, посуд повертається без миття. Не знаєте, скільки брати? Подзвоніть — порахуємо під ваше меню й кількість гостей.</p><p><em>Тестовий текст (мок-дані).</em></p>', 0);
